//! Label counting.

use super::LABEL_SEPARATOR;

/// Mirrors `idna::count_labels()`: one more than the number of `.` bytes.
///
/// Empty labels are counted, so `""` is 1, `"."` is 2 and `"a..b"` is 3. The
/// C++ counter is an `int`, which is what the return type reflects.
pub fn count_labels(input: &[u8]) -> i32 {
    let dots = input.iter().filter(|&&b| b == LABEL_SEPARATOR).count();
    dots as i32 + 1
}
