//! Case folding and normalization.

/// Mirrors `idna::to_lower()`, which is
/// `std::transform(s.begin(), s.end(), out.begin(), ::tolower)`.
///
/// `::tolower` runs in the default "C" locale, so only `A`..=`Z` shift by 32;
/// every other byte — including the continuation bytes of a multi-byte UTF-8
/// sequence — is returned unchanged. Folding byte-wise is therefore both
/// faithful and safe: it never rewrites a non-ASCII code point.
pub fn to_lower(input: &[u8]) -> Vec<u8> {
    input.iter().map(|&b| b.to_ascii_lowercase()).collect()
}

/// Mirrors `idna::normalize()`, which forwards straight to `to_lower()`.
pub fn normalize(input: &[u8]) -> Vec<u8> {
    to_lower(input)
}
