# ---- run one binary with an exact bytes argv list, capture stdout + status ----
sub run1 {
  my ($exe, $args) = @_;
  pipe(my $r, my $w) or die "pipe: $!";
  my $pid = fork(); die "fork: $!" unless defined $pid;
  if ($pid == 0) {
    close $r;
    open(STDOUT, '>&', $w) or exit 127;
    open(STDERR, '>', '/dev/null');
    exec { $exe } ($exe, @$args);
    exit 127;
  }
  close $w;
  binmode $r;
  local $/; my $out = <$r>; close $r;
  waitpid($pid, 0); my $st = $?;
  $out = '' unless defined $out;
  return ($out, $st);
}

# ---- bash $'...' ANSI-C quoting of arbitrary bytes (NUL impossible in argv) ----
sub q_ansi {
  my ($s) = @_;
  my $o = "\$'";
  for my $c (unpack('C*', $s)) {
    if ($c >= 0x20 && $c <= 0x7e && $c != 0x27 && $c != 0x5c) { $o .= chr($c) }
    else { $o .= sprintf('\\x%02x', $c) }
  }
  return $o . "'";
}
sub repro {
  my ($args) = @_;
  return join(' ', map { q_ansi($_) } @$args);
}

my $total = 0; my $bad = 0; my @found;

sub check {
  my ($label, @args) = @_;
