  my ($co2, $cs2) = run1($CPP, \@args);
  my ($ro2, $rs2) = run1($RS,  \@args);
  my $stable = ($co2 eq $co && $ro2 eq $ro && $cs2 == $cs && $rs2 == $rs);
  $bad++;
  my $id = sprintf("m%04d", $bad);
  for my $p (["$DIR/$id.c.out",$co], ["$DIR/$id.r.out",$ro]) {
    open(my $fh, '>', $p->[0]) or die; binmode $fh; print $fh $p->[1]; close $fh;
  }
  my $cmpst = system("cmp", "-s", "$DIR/$id.c.out", "$DIR/$id.r.out");
  my $rc = repro(\@args);
  print "MISMATCH [$id] group=$label stable=", ($stable?"YES":"NO"),
        " cmp_rc=", ($cmpst>>8), " exit_cpp=", ($cs>>8), "(raw $cs)",
        " exit_rs=", ($rs>>8), "(raw $rs)\n";
  print "  ARGS  : $rc\n";
  print "  CPPOUT: ", q_ansi($co), "\n";
  print "  RSOUT : ", q_ansi($ro), "\n";
  print "  REPRO : \"$CPP\" $rc > /tmp/c.out; \"$RS\" $rc > /tmp/r.out; cmp /tmp/c.out /tmp/r.out\n";
